using Captovix;
using System.Text.Json;
int n=0;void Check(bool value,string message){if(!value)throw new Exception(message);n++;Console.WriteLine("PASS: "+message);}void Reject(Action action,string message){try{action();}catch(ArgumentException){Check(true,message);return;}catch(System.IO.InvalidDataException){Check(true,message);return;}throw new Exception(message);}bool Near(double a,double b)=>Math.Abs(a-b)<1e-5;
var view=new PixelRect(0,0,400,300);var initial=new ImageAppearance();string original=JsonSerializer.Serialize(initial);var inside=CanvasEditing.FitContent(view,initial,new(20,20,100,100));Check(JsonSerializer.Serialize(inside)==original,"Inside object adds no margins and does not mutate original appearance");
var top=CanvasEditing.FitContent(view,initial,new(40,-37,100,80));Check(top.ExtendTop==37&&top.ExtendLeft==0&&top.ExtendRight==0&&top.ExtendBottom==0,"Object above image adds exactly the top edge");var topLayout=new ImageLayout(view,top);Check(topLayout.Width==400&&topLayout.Height==337&&topLayout.ToOutput(0,0)==new ImagePoint(0,37),"Top expansion preserves source pixels and horizontal extent");
var fractional=CanvasEditing.FitContent(view,initial,new(20,-37.2,100,80));Check(fractional.ExtendTop==38,"Only fractional final pixel is rounded upward, without a fixed buffer");
foreach(var item in new[]{(new ImageRect(-25,50,50,50),25,0,0,0),(new ImageRect(370,50,60,50),0,0,30,0),(new ImageRect(50,280,50,40),0,0,0,20),(new ImageRect(-10,-20,430,350),10,20,20,30)}){var a=CanvasEditing.FitContent(view,initial,item.Item1);Check(a.ExtendLeft==item.Item2&&a.ExtendTop==item.Item3&&a.ExtendRight==item.Item4&&a.ExtendBottom==item.Item5,"Only occupied edges expand: "+item.Item1);}
for(int turn=0;turn<4;turn++)foreach(bool flip in new[]{false,true})foreach(int scale in new[]{1,2}){
 var style=new ImageAppearance{QuarterTurns=turn,FlipHorizontal=flip};var natural=ImageLayout.Natural(view,style);style.ResizeWidth=natural.Width*scale;style.ResizeHeight=natural.Height*scale;var l=new ImageLayout(view,style);var source=ObjectPrecision.Map(new(30,-19,100,60),l,true);var next=CanvasEditing.FitContent(view,style,new(source.X,source.Y,source.Width,source.Height));var output=new ImageLayout(view,next);
 Check(output.Width==l.Width&&output.Height==l.Height+19&&next.ExtendTop==19&&next.ExtendLeft==0&&next.ExtendRight==0,"Expansion follows display top across rotation/flip/resize "+turn+"/"+flip+"/"+scale);
 var oldPoint=l.ToOutput(100,100);var point=output.ToOutput(100,100);Check(Near(point.X,oldPoint.X)&&Near(point.Y,oldPoint.Y+19),"Source mapping is translated without resampling");
}
var manual=CanvasEditing.Expand(view,new(),10,20,30,40);var already=CanvasEditing.FitContent(view,manual,new(-5,-10,30,30));Check(JsonSerializer.Serialize(already)==JsonSerializer.Serialize(manual),"Existing manual margins are retained without duplication");
var cropped=CanvasEditing.CropOutput(view,new(),new(10,20,200,150));var cropGrow=CanvasEditing.FitContent(view,cropped,new(30,0,30,50));Check(new ImageLayout(view,cropGrow).Height==170&&cropGrow.OutputCrop?.X==10,"Expansion after crop preserves its source origin");
Reject(()=>CanvasEditing.FitContent(view,initial,new(double.NaN,0,20,20)),"Non-finite bounds rejected");Reject(()=>CanvasEditing.FitContent(view,initial,new(-40000,0,20,20)),"Oversized expansion rejected");
foreach(var sample in new[]{(new PixelRect(0,0,1920,1080),new PixelRect(0,0,1920,1040),new PixelRect(0,0,1920,1040)),(new PixelRect(-1920,0,1920,1080),new PixelRect(-1880,0,1880,1080),new PixelRect(40,0,1880,1080)),(new PixelRect(0,-1440,2560,1440),new PixelRect(0,-1400,2560,1400),new PixelRect(0,40,2560,1400)),(new PixelRect(1920,0,3840,2160),new PixelRect(1920,0,3840,2080),new PixelRect(0,0,3840,2080))})Check(WorkAreaGeometry.Maximized(sample.Item1,sample.Item2)==sample.Item3,"Maximize uses physical monitor work area: "+sample.Item1);
Reject(()=>WorkAreaGeometry.Maximized(view,new(1000,1000,20,20)),"Unrelated work area is rejected");
foreach(var shape in Enum.GetValues<CalloutStyle>())foreach(int font in new[]{8,28,96,240})foreach(int padding in new[]{0,30,200}){var a=new Annotation{Kind=AnnotationKind.Callout,CalloutStyle=shape,FontSize=font,TextPadding=padding};double fraction=TextStudio.ContentFraction(shape),width=TextStudio.MinimumBodyWidth(a);Check(fraction>=.5&&fraction<=1&&Near(width*fraction-2*padding,Math.Max(80,font*4)),"Readable callout content width: "+shape+"/"+font+"/"+padding);double h=TextStudio.FittedBodyHeight(a,40,2);Check(h>=36&&Near(h*fraction-2*padding,42),"Auto height uses actual text metrics: "+shape+"/"+font+"/"+padding);}
var session=new EditorSession(new(){OriginalWidth=400,OriginalHeight=300});session.Change(d=>d.Appearance=CanvasEditing.FitContent(d.Viewport,d.Appearance,new(0,-30,100,60)));session.Undo();Check(!session.Document.Appearance.HasEdits,"Undo removes precise expansion");session.Redo();Check(session.Document.Appearance.ExtendTop==30,"Redo restores precise expansion");
Console.WriteLine($"{n} refinement/canvas/work-area checks passed.");
